import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";import"./chunks/assets.NJs4UO-Q.js";var i=JSON.parse(`{"title":"联系与反馈","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code/contact-and-feedback.md","filePath":"zh/kimi-code/contact-and-feedback.md"}`),a={name:`kimi-code/contact-and-feedback.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="联系与反馈" tabindex="-1">联系与反馈 <a class="header-anchor" href="#联系与反馈" aria-label="Permalink to “联系与反馈”">​</a></h1><p>遇到问题、有功能建议，或想直接和团队交流？先看能否自助解决，若仍需要帮助，再通过下方任一渠道联系我们。</p><h2 id="反馈前的自助排查" tabindex="-1">反馈前的自助排查 <a class="header-anchor" href="#反馈前的自助排查" aria-label="Permalink to “反馈前的自助排查”">​</a></h2><p><a href="/code/docs/kimi-code/faq.html">常见问题</a>收录了高频疑问，<a href="/code/docs/kimi-code/error-reference.html">错误参考</a>解释了常见的服务端报错，遇到问题可以先到这两处查一查。</p><p>也可以先自查几项，不少能就地解决：</p><ul><li>CLI 是否为最新版本（运行 <code>kimi --version</code> 查看，必要时更新）</li><li>网络能否连上 Kimi 服务：公司网络或代理有可能拦截 <code>api.kimi.com</code></li><li>是否已登录、API Key 是否有效</li><li>当前工作目录与文件读写权限是否正常</li></ul><h2 id="反馈渠道" tabindex="-1">反馈渠道 <a class="header-anchor" href="#反馈渠道" aria-label="Permalink to “反馈渠道”">​</a></h2><p>若仍未解决，或想提交建议、直接与团队交流，可通过以下渠道联系我们。</p><h3 id="加入飞书交流群" tabindex="-1">加入飞书交流群 <a class="header-anchor" href="#加入飞书交流群" aria-label="Permalink to “加入飞书交流群”">​</a></h3><p>用飞书扫描下方二维码加入 Kimi Code 用户群，与团队和其他用户实时交流、获取帮助。</p><div style="display:flex;justify-content:center;margin-top:8px;"><img src="/code/docs/images/zh/kimi-code/contact-and-feedback/feishu-group.png" alt="Kimi Code 用户群飞书二维码" style="max-width:420px;width:100%;border-radius:8px;"></div><h3 id="在-cli-中直接反馈-推荐" tabindex="-1">在 CLI 中直接反馈（推荐） <a class="header-anchor" href="#在-cli-中直接反馈-推荐" aria-label="Permalink to “在 CLI 中直接反馈（推荐）”">​</a></h3><p>在 Kimi Code CLI 交互界面中输入 <code>/feedback</code>，按提示选择随反馈一起上传的内容：</p><ul><li><strong>No attachment</strong>：仅提交文字反馈</li><li><strong>Logs only</strong>：附带本次会话的 wire events 与诊断日志；<strong>建议至少选这项</strong>，方便我们定位问题</li><li><strong>Logs + codebase</strong>：进一步附带代码库以做深入诊断；<code>.env</code>、配置文件、密钥等敏感文件会自动排除，附件仅用于诊断、绝不外泄</li></ul><p>提交成功后，CLI 会显示本次的 <code>Session</code> 与 <code>Feedback ID</code>。到上方的飞书交流群把这两个 ID 发出来即可跟进。</p><h3 id="github-issues" tabindex="-1">GitHub Issues <a class="header-anchor" href="#github-issues" aria-label="Permalink to “GitHub Issues”">​</a></h3><p>前往 Kimi Code CLI 仓库检索已有问题或新建 issue：</p><ul><li><a href="https://github.com/MoonshotAI/kimi-code/issues" target="_blank" rel="noreferrer">https://github.com/MoonshotAI/kimi-code/issues</a></li></ul><h3 id="邮件" tabindex="-1">邮件 <a class="header-anchor" href="#邮件" aria-label="Permalink to “邮件”">​</a></h3><p>发送邮件至 <a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a>。为便于我们快速定位，建议在邮件中附上：</p><ul><li>问题描述</li><li>复现步骤</li><li>环境信息（可运行 <code>kimi --version</code> 获取）</li><li>相关错误日志——在 CLI 中运行 <code>/export-debug-zip</code>（或命令行 <code>kimi export</code>）导出调试 ZIP，已自动打包诊断日志，作为附件发来即可</li></ul><h2 id="账号申诉" tabindex="-1">账号申诉 <a class="header-anchor" href="#账号申诉" aria-label="Permalink to “账号申诉”">​</a></h2><p>若账号被误封或需投诉举报，请发送邮件至 <a href="mailto:support@moonshot.cn" target="_blank" rel="noreferrer">support@moonshot.cn</a>，并附上账号 ID、发生时间与相关情况说明。</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};